package com.cpf.starter.integration.graphql;
import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("cpf.integration.graphql") public class CpfGraphqlProperties { private boolean enabled; private int maxDepth=12; private int maxComplexity=250; private int maxDocumentLength=32768; private boolean introspection; private boolean graphiql; public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public int getMaxDepth(){return maxDepth;} public void setMaxDepth(int v){maxDepth=Math.max(1,v);} public int getMaxComplexity(){return maxComplexity;} public void setMaxComplexity(int v){maxComplexity=Math.max(1,v);} public int getMaxDocumentLength(){return maxDocumentLength;} public void setMaxDocumentLength(int v){maxDocumentLength=Math.max(1024,v);} public boolean isIntrospection(){return introspection;} public void setIntrospection(boolean v){introspection=v;} public boolean isGraphiql(){return graphiql;} public void setGraphiql(boolean v){graphiql=v;} }
